        headers: { "Content-Type": "application/json" },
      });
    }

    return Response.json({ error: "not found" }, { status: 404 });
  },
};

async function saveArtifactsToR2(
  container: DurableObjectStub<DbtContainer>,
  bucket: R2Bucket
) {
  try {
    const response = await container.fetch("http://container/artifacts", {
      method: "POST",
    });
    const data = (await response.json()) as {
      artifacts: string[];
      data: Record<string, unknown>;
    };

    const timestamp = new Date().toISOString().replace(/[:.]/g, "-");

    for (const [filename, content] of Object.entries(data.data)) {
      // 最新版を保存
      await bucket.put(`dbt-core/latest/${filename}`, JSON.stringify(content), {
        httpMetadata: { contentType: "application/json" },
      });

      // タイムスタンプ付きアーカイブ
      await bucket.put(
        `dbt-core/history/${timestamp}/${filename}`,
        JSON.stringify(content),
        { httpMetadata: { contentType: "application/json" } }
      );
    }

    console.log(
      `Saved ${data.artifacts.length} artifacts to R2: ${data.artifacts.join(", ")}`
    );
  } catch (error) {
    console.error("Failed to save artifacts to R2:", error);
  }
}

